MATCH (n) WHERE exists {
  (n)-[r]->() WHERE type(r) = 'NA'
}
RETURN n

MATCH (n:X {name: 'A'})
SET n += { }
RETURN n

MATCH (n) WHERE exists {
  MATCH (m) WHERE exists {
    (n)-[]->(m) WHERE n.prop = m.prop
  }
  RETURN true
}
RETURN n

